package icc.pap.camposmonitor;

import icc.pap.models.Lectura;
import icc.pap.models.Reporte;

public class App {

    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        runLectura();
        runTransformaciones();
    }

    private static void runLectura(){
        Lectura<Double> temperatura = new Lectura<>("s01", 22.5, "C");
        Lectura<Integer> ocupacion = new Lectura<>("s02", 18, "personas");

        System.out.println("Lectura de CampusMonitor");
        System.out.println(temperatura.getIdSensor() + "|" + temperatura.getValor() + temperatura.getUnidad() );
        System.out.println(ocupacion.getIdSensor() + "|" + ocupacion.getValor() + ocupacion.getUnidad() );


        System.out.println("Valores recuperados sin casting:");
        System.out.println("Temperatura: " + temperatura.getValor());
        System.out.println("Ocupacion: " + ocupacion.getValor());
    }

    private static void runTransformaciones(){
        System.out.println("==========Transformaciones==========");

        //Transformacion a s01
        Lectura<Double> temperatura = new Lectura<>("s01", 22.5, "C");

        
        System.out.println("Original: " + temperatura.getIdSensor() + "|" + temperatura.getValor() + temperatura.getUnidad() );        
        Lectura<Double> temperaturaTransformada = temperatura.transformar( c -> c -9.0/5.0+32,"F");
        System.out.println("Transformado: " + temperaturaTransformada.getIdSensor() + " | " + temperaturaTransformada.getValor() + " | "+temperaturaTransformada.getUnidad() );

        //Tranformaciones de S02
        Lectura<Integer> ocupacion = new Lectura<>("s02", 18, "personas");
        System.out.println("Original: " + ocupacion.getIdSensor() + " | " + ocupacion.getValor() + ocupacion.getUnidad() );

        Lectura<String> ocupacionTranformada = ocupacion.transformar(v ->  v + " Persona",  "Unidad texto");

        System.out.println("Transformada: " + ocupacionTranformada.getIdSensor() + " | " + ocupacionTranformada.getValor() + " | " +ocupacionTranformada.getUnidad() );


        // Double a object

        Lectura<Double> algoNuevo = new Lectura<>("s01", 22.5, "C");
        System.out.println("Original: " + algoNuevo.getIdSensor() + "|" + algoNuevo.getValor() + algoNuevo.getUnidad() );        
   
        Lectura<Reporte> objetosTransformar = new Lectura<Reporte>("s01", 
            new Reporte(
                algoNuevo.getIdSensor(),
                algoNuevo.getValor(),
                algoNuevo.getUnidad()),"C");
        

        System.out.println("Transformado: " + objetosTransformar.getIdSensor() + " | " + objetosTransformar.getValor() + " | " + objetosTransformar.getUnidad());
        }

}
                                                